import styled from '@emotion/styled';

export const StyledWaterfallBaseContainer = styled.div({
  width: '100%',
  height: '100%',
  backgroundColor: '#FFFFFF',
  borderRadius: '16px',
  border: '1px solid #1414141f',
});

export const StyledGlobalSliderGrid = styled.div({
  display: 'flex',
  marginTop: '16px',
  flexDirection: 'column',
  gap: '16px',
});
